// Regenerates lib/services/app_version.dart from pubspec.yaml.
//   dart run tool/gen_version.dart
// The test asserts the two agree, so this only has to be run when the version
// changes; forgetting is caught rather than shipped.
import 'dart:io';

void main() {
  final pubspec = File('pubspec.yaml').readAsStringSync();
  final m = RegExp(r'^version:\s*(\S+)', multiLine: true).firstMatch(pubspec);
  if (m == null) {
    stderr.writeln('no version: line in pubspec.yaml');
    exit(1);
  }
  final v = m.group(1)!;
  File('lib/services/app_version.dart').writeAsStringSync(
    '// GENERATED by tool/gen_version.dart from pubspec.yaml. Do not edit by hand.\n'
    '//\n'
    '// It exists so the feedback email can report which build a report came from\n'
    '// without adding a package dependency to read it at runtime.\n'
    '// test/services/app_version_test.dart fails if this drifts from pubspec.\n'
    "const String kAppVersion = '\$v';\n",
  );
  stdout.writeln('app_version.dart -> \$v');
}
